package com.alxt.SoundPad;
import android.app.*;import android.content.*;import android.media.projection.*;import android.os.*;import android.speech.tts.TextToSpeech;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity { static final int REQ=8; TextToSpeech tts; EditText words; TextView status; public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);TextView h=new TextView(this);h.setText("SoundPad 2.0\nInternal audio recorder and speech tools");h.setTextSize(23);l.addView(h);status=new TextView(this);status.setText("Ready. Android 10+ required for playback capture.");l.addView(status);Button start=new Button(this);start.setText("Start internal audio recording");start.setOnClickListener(v->((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).createScreenCaptureIntent().also(i->startActivityForResult(i,REQ)));l.addView(start);Button stop=new Button(this);stop.setText("Stop recording");stop.setOnClickListener(v->startService(new Intent(this,CaptureService.class).setAction("STOP")));l.addView(stop);words=new EditText(this);words.setHint("Text to speak");words.setMinLines(3);l.addView(words);Button speak=new Button(this);speak.setText("Speak text");speak.setOnClickListener(v->{if(tts!=null)tts.speak(words.getText().toString(),TextToSpeech.QUEUE_FLUSH,null,"sp");});l.addView(speak);setContentView(l);tts=new TextToSpeech(this,s->{if(s==0)tts.setLanguage(Locale.getDefault());});} protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==REQ&&c==-1){Intent i=new Intent(this,CaptureService.class).setAction("START").putExtra("code",c).putExtra("data",d);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("Capture started; source apps may block capture.");}}protected void onDestroy(){if(tts!=null)tts.shutdown();super.onDestroy();}}
